os.chdir('/home/user/guidebook'); sys.path.insert(0,'workplan/pipeline-state-graph')
import build_graph as b
T=b.Tree('.'); atoms,_=b.load_atoms()
conf=yaml.safe_load(open('workplan/pipeline-state-graph/conflicts.yaml'))
mach=yaml.safe_load(open('workplan/pipeline-state-graph/machines.yaml'))
