contract=yaml.safe_load(open('governance/pipeline-contract.yaml'))
P=b.make_probes(); b.ATOMS_FOR_PROBES.update(atoms); probes=b.run_probes(T,P)
stages=T.stages
def atom_stage(ids):
    c=collections.Counter()
    for i in ids:
        a=atoms.get(i)
        if not a: continue
        for s in (a['scope'].get('stages') or []): 
            if s!='cross': c[s]+=1
    if not c: return 'cross'
    top=c.most_common(2)
    return top[0][0] if len(top)==1 or top[0][1]>top[1][1] else 'cross'
# usage of verbs from command logs
use=collections.Counter()
pat=re.compile(r'(?:^|[;&|\n]\s*|\s)(?:[A-Z_]+=\S+\s+)*python3?\s+(?:-\S+\s+)*(?:\./)?scripts/db\.py\s+([a-z][a-z\-]+)')
for f in glob.glob('scratchpad/*/commands.jsonl'):
    for l in open(f,errors='replace'):
        try: d=json.loads(l)
        except: continue
        cmd=d.get('command') or ''
        if re.match(r'\s*(grep|rg|echo|cat|git|sed|awk|head|tail|wc)\b',cmd): continue
        for m in pat.finditer(cmd):
            if m.group(1) in T.verbs: use[m.group(1)]+=1
def callers(t):
    out=subprocess.run(['git','grep','-l','-w',t,'--','scripts','schemas','tools','.claude','.github','governance/check-registry.yaml','governance/pipeline-contract.yaml','CLAUDE.md','skills'],capture_output=True,text=True).stdout.split('\n')
    return [f for f in out if f and 'scripts/migrations/' not in f and '/tests/' not in f and not f.endswith('.html')]
unw={(x['child']):x for x in T.unwritable_set()}
reg={c['id']:c for c in T.registry['checks']}; quar={q['id']:q for q in T.registry.get('quarantine',[])}
inv={}
for s in stages+['infrastructure']:
    tabs=[t for t in T.tables if T.stage(t)==s]
    rows=[]
    for t in tabs:
        fl=[]
        if T.rows[t]==0: fl.append('EMPTY')
        if t not in T.writers: fl.append('NO-WRITER')
        if t in unw and not unw[t]['parent_written_by_same_verb']: fl.append('UNWRITABLE')
        rows.append(dict(table=t,rows=T.rows[t],writers=T.writers.get(t,[]),flags=fl,callers=len(callers(t)) if 'EMPTY' in fl else None))
    verbs=[v for v,d in T.verbs.items() if d['writes'] and all(T.stage(t)==s for t in d['writes'] if t in T.t2s)]
    crit=[c for st in contract['stages'] if st['id']==s for c in st.get('criteria',[])]
    cks=[]
    for c in crit:
        ck=c.get('check'); 
        if ck and ck!='None':
            cid=[k for k,v in reg.items() if ck in ' '.join(map(str,v.get('cmd',[])))]
            cks.append((c['id'],ck,cid,[reg[k]['level'] for k in cid]))
        else: cks.append((c['id'],None,[],[]))
    cf=[x['id'] for x in conf['conflicts'] if atom_stage(x['atoms'])==s]
    pr={k:v['verdict'] for k,v in probes.items() if atom_stage(v['atoms'])==s}
    ms=[m['id'] for m in mach['machines'] if s in m['stage']]
    comps=[c['name'] for c in caps['components'] if c['stage']==s]
    inv[s]=dict(tables=rows,verbs={v:use[v] for v in verbs},contract_criteria=cks,conflicts=cf,probes=pr,machines=ms,components=comps)
json.dump(inv,open('/tmp/claude-0/-home-user-guidebook/db856d85-2082-5d35-9529-aa996506261b/scratchpad/plan/stage_inventory.json','w'),indent=1,default=str)
allc=[x['id'] for x in conf['conflicts']]
placed={c for s in inv.values() for c in s['conflicts']}
print("conflicts placed:",len(placed),"of",len(allc),"| cross:",[c for c in allc if c not in placed])
for s,d in inv.items():
    t=d['tables']
    print(f"\n### {s}: tables={len(t)} empty={sum('EMPTY' in x['flags'] for x in t)} nowriter={sum('NO-WRITER' in x['flags'] for x in t)} unwritable={sum('UNWRITABLE' in x['flags'] for x in t)} verbs={len(d['verbs'])} machines={d['machines']} conflicts={d['conflicts']}")
    print("  probes:",d['probes'])
    print("  criteria->checks:",[(a,c,e) for a,c,e,_ in d['contract_criteria']])
